import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit

base = 'https://www.liveca.ca/'
root = Path('products/services/liveca-invoice-pilot')
raw = (root / 'raw/homepage.html').read_bytes()
workflow = re.compile(r'invoic|accounts payable|bookkeep|bill payment|payables', re.I)
route = re.compile(r'contact|consultation|book a call|get started|work with us', re.I)

class Homepage(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.fragments = []
        self.links = []
        self.anchor = None

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style', 'template'):
            self.hidden += 1
        if tag == 'a' and not self.hidden:
            self.anchor = (dict(attrs).get('href', ''), [])

    def handle_endtag(self, tag):
        if tag in ('script', 'style', 'template') and self.hidden:
            self.hidden -= 1
        if tag == 'a' and self.anchor is not None:
            href, parts = self.anchor
            label = ' '.join(parts)
            url = urljoin(base, href)
            parsed = urlsplit(url)
            if href and parsed.scheme == 'https' and parsed.hostname in ('www.liveca.ca', 'liveca.ca') and (workflow.search(label + ' ' + parsed.path) or route.search(label + ' ' + parsed.path)):
                self.links.append({'label': label, 'url': url})
            self.anchor = None

    def handle_data(self, data):
        if self.hidden:
            return
        text = ' '.join(data.split())
        if not text:
            return
        if self.anchor is not None:
            self.anchor[1].append(text)
        if workflow.search(text) and text not in self.fragments:
            self.fragments.append(text[:500])

page = Homepage()
page.feed(raw.decode('utf-8', errors='replace'))
result = {'source': base, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'workflow_text_fragments': page.fragments[:25], 'first_party_navigation_candidates': [dict(item) for item in dict.fromkeys(tuple(link.items()) for link in page.links)][:25], 'scope': 'Navigation and text pointers from the saved homepage. Verify wording in context before treating it as workflow or inquiry-route evidence.'}
out = root / 'director-homepage-pointers.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
